class Solution {
public:
    std::vector<int> minAvailableDuration(std::vector<std::vector<int>>& slots1, std::vector<std::vector<int>>& slots2, int duration) {
        std::sort(slots1.begin(), slots1.end());
        std::sort(slots2.begin(), slots2.end());
        int i = 0, j = 0;
        int n1 = slots1.size(), n2 = slots2.size();
        while (i < n1 && j < n2) {
            int start = std::max(slots1[i][0], slots2[j][0]);
            int end = std::min(slots1[i][1], slots2[j][1]);
            if (end - start >= duration) {
                return {start, start + duration};
            }
            if (slots1[i][1] < slots2[j][1]) {
                i++;
            } else {
                j++;
            }
        }
        return {};
    }
};

class Solution {
    public java.util.List<Integer> minAvailableDuration(int[][] slots1, int[][] slots2, int duration) {
        java.util.Arrays.sort(slots1, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.Arrays.sort(slots2, (a, b) -> Integer.compare(a[0], b[0]));
        int i = 0, j = 0;
        int n1 = slots1.length, n2 = slots2.length;
        while (i < n1 && j < n2) {
            int start = Math.max(slots1[i][0], slots2[j][0]);
            int end = Math.min(slots1[i][1], slots2[j][1]);
            if (end - start >= duration) {
                return java.util.List.of(start, start + duration);
            }
            if (slots1[i][1] < slots2[j][1]) {
                i++;
            } else {
                j++;
            }
        }
        return java.util.List.of();
    }
}

